import { writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { join } from "node:path";

const require = createRequire(join(process.env.HOME, "development/stallion/package.json"));
const { chromium, devices } = require("playwright");
const DIR = join(process.env.HOME, "development/.tmp/stallion-gesture");
const URL_ = `http://100.104.44.51:5173/b/gesture-${Date.now()}`;

const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({ ...devices["Galaxy Tab S9"] });
const page = await context.newPage();
const errors = [];
page.on("console", (m) => {
  if (m.type() === "error" && !/favicon/.test(`${m.text()} ${m.location().url}`)) errors.push(m.text());
});
page.on("pageerror", (e) => errors.push(e.message));

const objects = () =>
  page.evaluate(
    () =>
      new Promise((resolve, reject) => {
        const r = indexedDB.open("stallion");
        r.onerror = () => reject(r.error);
        r.onsuccess = () => {
          const db = r.result;
          if (!db.objectStoreNames.contains("objects")) return resolve(0);
          const c = db.transaction("objects").objectStore("objects").count();
          c.onsuccess = () => resolve(c.result);
        };
      }),
  );

const ink = async (name) => {
  const buffer = await page.screenshot();
  writeFileSync(join(DIR, `${name}.png`), buffer);
  return page.evaluate(async (b64) => {
    const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
    const bitmap = await createImageBitmap(new Blob([bytes], { type: "image/png" }));
    const canvas = new OffscreenCanvas(bitmap.width, bitmap.height);
    const ctx = canvas.getContext("2d");
    ctx.drawImage(bitmap, 0, 0);
    const d = ctx.getImageData(0, 0, bitmap.width, bitmap.height / 2 | 0).data;
    let dark = 0;
    for (let i = 0; i < d.length; i += 4) if (d[i] + d[i + 1] + d[i + 2] < 200) dark++;
    return dark;
  }, buffer.toString("base64"));
};

await page.goto(URL_, { waitUntil: "load" });
await page.locator("canvas.surface").waitFor({ state: "visible" });
await page.waitForTimeout(800);
const cdp = await context.newCDPSession(page);
const touch = (type, points) =>
  cdp.send("Input.dispatchTouchEvent", {
    type,
    touchPoints: points.map(([x, y], i) => ({ x, y, id: i + 1, radiusX: 2, radiusY: 2 })),
  });
const wait = (ms) => page.waitForTimeout(ms);

const vp = page.viewportSize();
const y = Math.round(vp.height * 0.25);
const x0 = Math.round(vp.width * 0.3);
const x1 = Math.round(vp.width * 0.7);
const blank = await ink("0-blank");

await touch("touchStart", [[x0, y]]);
for (let x = x0 + 10; x <= x1; x += 10) await touch("touchMove", [[x, y]]);
await touch("touchEnd", []);
await wait(800);
const drawn = { ink: await ink("1-drawn"), objects: await objects() };

await page.getByRole("button", { name: "Eraser" }).tap();
await wait(300);

const mid = Math.round((x0 + x1) / 2);
await touch("touchStart", [[mid, y]]);
await wait(30);
await touch("touchStart", [[mid, y], [mid + 150, y + 40]]);
const dy = 120;
for (let s = 1; s <= 12; s++) await touch("touchMove", [[mid, y + (s * dy) / 12], [mid + 150, y + 40 + (s * dy) / 12]]);
await touch("touchEnd", [[mid + 150, y + 40 + dy]]);
await touch("touchEnd", []);
await wait(800);
const panned = { ink: await ink("2-after-two-finger-pan"), objects: await objects() };

await touch("touchStart", [[mid, y + dy]]);
await touch("touchEnd", []);
await wait(800);
const tapped = { ink: await ink("3-after-tap"), objects: await objects() };

console.log(JSON.stringify({ url: URL_, blank, drawn, panned, tapped, errors }, null, 1));
await browser.close();
EOF
